103:       data.records = [record, ...(data.records ?? [])]
104:       storage.set(key, data)
105:       return record
106:       } finally { submitting = false }
107:     }
108:     return { saveDraft, loadDraft, draftSavedAt, submitInspection, submitRescue, getRecord, getDraftByKey, fetchHistoryPage, countHistory }
109:   })
110: }
