78:     /**
79:      * 小区选择：按名称模糊搜已备案小区
80:      * <p>
81:      * G 端可看全部；物业侧要按 operableProjectList 授权过滤，走 B 端接口，不在本接口。
82:      */
83:     @ApiOperation("小区选择（按名称搜索已备案小区）")
84:     @GetMapping("/complex/options")
85:     public JsonResult<List<Option>> complexOptions(@RequestParam String complexName) {
86:         if (StrUtil.isBlank(complexName)) {
87:             return JsonResult.success(Collections.emptyList());
88:         }
89:         List<ComplexDto> matched = remoteComplexService.listByName(complexName.trim()).getData();
90:         if (CollUtil.isEmpty(matched)) {
91:             return JsonResult.success(Collections.emptyList());
92:         }
93:         List<Long> ids = matched.stream()
94:                 .map(ComplexDto::getComplexId)
95:                 .filter(Objects::nonNull)
96:                 .limit(MAX_SIZE)
97:                 .collect(Collectors.toList());
98:         if (ids.isEmpty()) {
99:             return JsonResult.success(Collections.emptyList());
100:         }
101:         ComplexQueryDto query = new ComplexQueryDto();
102:         query.setComplexIds(ids);
103:         // 只返回已备案小区
104:         query.setBizState("2");
105:         List<ComplexListVo> list = remoteComplexService.list(query).getData();
106:         if (CollUtil.isEmpty(list)) {
107:             return JsonResult.success(Collections.emptyList());
108:         }
109:         List<Option> result = new ArrayList<>(list.size());
110:         for (ComplexListVo vo : list) {
111:             Option option = new Option();
112:             option.setCode(String.valueOf(vo.getComplexId()));
113:             option.setName(vo.getComplexName());
114:             option.setExtra(StrUtil.blankToDefault(vo.getSubdistrict(), "") + "|" + StrUtil.blankToDefault(vo.getCommunity(), ""));
115:             result.add(option);
116:         }
117:         return JsonResult.success(result);
118:     }
