179:     /**
180:      * 行政区域：把部门权限树的节点解析成区划编码
181:      * <p>
182:      * 发布范围的下拉用部门权限树（{@code /v2.0/system/dept/treeInPermission}），但小区是
183:      * 按 {@code T_COMPLEX.REGION / SUBDISTRICT / COMMUNITY} 编码存的，必须落回编码才能筛小区。
184:      * <p>
185:      * 不能拿部门子树去筛 {@code T_COMPLEX.DEPT_ID}：实测已备案小区 5526 个，归属部门类型里
186:      * {@code 13}（企业链授权小区）占 6926、{@code 32}（行政链小区）占 5613，
187:      * 行政树的子树覆盖不到企业链那批。
188:      */
189:     @ApiOperation("部门节点解析为区划编码（发布范围-行政区域）")
190:     @GetMapping("/dept/area")
191:     public JsonResult<AreaInfo> deptArea(@RequestParam Long deptId) {
192:         // 解析逻辑统一收敛在 FloodAreaResolver，求援工单的可见范围也复用这一套
193:         FloodAreaResolver.AreaScope scope = floodAreaResolver.resolveByDept(deptId);
194:         if (scope == null) {
195:             return JsonResult.success(null);
196:         }
197:         AreaInfo info = new AreaInfo();
198:         info.setDeptId(scope.getDeptId());
199:         info.setName(scope.getDeptName());
200:         info.setDeptType(scope.getDeptType());
201:         info.setRegionLevel(scope.getRegionLevel());
202:         info.setRegionCode(scope.getRegionCode());
203:         return JsonResult.success(info);
204:     }
205: 
206:     /**
207:      * 区划编码反查部门节点（编辑时回显部门树选中项）
208:      */
209:     @ApiOperation("区划编码反查部门节点（发布范围回显）")
210:     @GetMapping("/dept/byArea")
211:     public JsonResult<Long> deptByArea(@RequestParam String regionLevel,
212:                                        @RequestParam(required = false) String regionCode) {
213:         try {
214:             // 市级不落区划编码（NULL=全市），直接取部门树的根（苏州市，deptType=A）
215:             if (LEVEL_CITY.equals(regionLevel)) {
216:                 PageResult<SysDeptVo> page = remoteDeptService.pageByDeptType(1, 10, DEPT_TYPE_CITY);
217:                 List<SysDeptVo> rows = page == null ? null : page.getRows();
218:                 return JsonResult.success(CollUtil.isEmpty(rows) ? null : rows.get(0).getDeptId());
219:             }
220:             if (StrUtil.isBlank(regionCode)) {
221:                 return JsonResult.success(null);
222:             }
223:             if (LEVEL_DISTRICT.equals(regionLevel)) {
224:                 SysRegionVo vo = remoteRegionService.queryByRegionCode(regionCode).getData();
225:                 return JsonResult.success(vo == null ? null : vo.getDeptId());
226:             }
227:             if (LEVEL_SUBDISTRICT.equals(regionLevel)) {
228:                 SysSubdistrictVo vo = remoteSubdistrictService.queryBySubdistrictCode(regionCode).getData();
229:                 return JsonResult.success(vo == null ? null : vo.getDeptId());
230:             }
231:             if (LEVEL_COMMUNITY.equals(regionLevel)) {
232:                 SysCommunityVo vo = remoteCommunityService.queryByCommunityCode(regionCode).getData();
233:                 return JsonResult.success(vo == null ? null : vo.getDeptId());
234:             }
235:         } catch (Exception e) {
236:             logger.warn("区划编码反查部门失败, regionLevel={}, regionCode={}", regionLevel, regionCode, e);
237:         }
238:         // 市级或未匹配到：返回空，前端按“全市”处理
239:         return JsonResult.success(null);
240:     }
241: 
