243:      * 部门节点解析结果
244:      */
245:     @Data
246:     public static class AreaInfo {
247:         private Long deptId;
248:         private String name;
249:         /** 部门类型：A 市 / 0 区县 / 1 街道 / 2 社区 */
250:         private String deptType;
251:         /** 1 市 / 2 区县 / 3 街道 / 4 社区 */
252:         private String regionLevel;
253:         /** 区县=regionCode、街道=subdistrictCode、社区=communityCode；市级为空 */
254:         private String regionCode;
255:     }
