12: /**
13:  * 对称加密解密AES算法
14:  */
15: @Slf4j
16: public class AESUtil {
17: 
18:     private static final String TRANSFORMATION = "AES/CBC/PKCS5Padding";
19:     private static final String ALGORITHM = "AES";
20:     private static final String CHARSET = "utf-8";
21:     /**
22:      * 建议为16位或32位
23:      */
24:     private static final String KEY = "A-16-Byte-keyValA-16-Byte-keyVal";
25:     /**
26:      * 必须16位
27:      * 初始化向量IV不可以为32位，否则异常java.security.InvalidAlgorithmParameterException: Wrong IV length: must be 16 bytes long
28:      */
29:     private static final String IV = "A-16-Byte-String";
30: 
31:     /**
32:      * 加密
33:      *
34:      * @param context
35:      * @return
36:      */
37:     public static String encrypt(String context) {
38:         try {
39:             if (context == null) {
40:                 return null;
41:             }
42:             byte[] decode = context.getBytes(CHARSET);
43:             byte[] bytes = createKeyAndIv(decode, Cipher.ENCRYPT_MODE);
44:             return Base64.getEncoder().encodeToString(bytes);
45:         } catch (Exception e) {
46:             throw new RuntimeException("AES加密失败", e);
47:         }
48:     }
49: 
50:     /**
51:      * 解密
52:      *
53:      * @param context
54:      * @return
55:      */
56:     public static String decrypt(String context) {
57:         if (context == null || context.isEmpty()) {
58:             return null;
59:         }
60:         try {
61:             Base64.Decoder decoder = Base64.getDecoder();
62:             byte[] decode = decoder.decode(context);
63:             byte[] bytes = createKeyAndIv(decode, Cipher.DECRYPT_MODE);
64:             return new String(bytes, CHARSET);
65:         } catch (Exception e) {
66:             e.printStackTrace();
67:         }
68:         return null;
69:     }
70: 
71:     /**
72:      * 获取key & iv
73:      *
74:      * @param context
75:      * @param opmode
76:      * @return
77:      * @throws Exception
78:      */
79:     public static byte[] createKeyAndIv(byte[] context, int opmode) throws Exception {
80:         byte[] key = KEY.getBytes(CHARSET);
81:         byte[] iv = IV.getBytes(CHARSET);
82:         return cipherFilter(context, opmode, key, iv);
83:     }
84: 
85:     /**
86:      * 执行操作
87:      *
88:      * @param context
89:      * @param opmode
90:      * @param key
91:      * @param iv
92:      * @return
93:      * @throws Exception
94:      */
95:     public static byte[] cipherFilter(byte[] context, int opmode, byte[] key, byte[] iv) throws Exception {
96:         Key secretKeySpec = new SecretKeySpec(key, ALGORITHM);
97:         AlgorithmParameterSpec ivParameterSpec = new IvParameterSpec(iv);
98:         Cipher cipher = Cipher.getInstance(TRANSFORMATION);
99:         cipher.init(opmode, secretKeySpec, ivParameterSpec);
100:         return cipher.doFinal(context);
101:     }
