node "$env:TEMP\enc.js"

$enc = 'eKN39gNve33t8CYGQ+iBOw=='
$body = @{ username='zsbase'; password=$enc } | ConvertTo-Json
try {
  $r = Invoke-WebRequest -Uri "http://127.0.0.1:9211/v2.0/security/auth/login" -Method Post -Body $body -ContentType "application/json" -TimeoutSec 15 -UseBasicParsing
  Write-Output "STATUS: $($r.StatusCode)"
  $j = $r.Content | ConvertFrom-Json
  Write-Output "code=$($j.code) msg=$($j.msg)"
  Write-Output "accessToken=$($j.data.accessToken)"
  Write-Output "user=$($j.data.username) dept=$($j.data.deptId)"
  $j.data.accessToken | Out-File "$env:TEMP\token.txt" -Encoding ascii -NoNewline
} catch {
  Write-Output "ERR: $($_.Exception.Message)"
  if ($_.Exception.Response) { $sr = New-Object System.IO.StreamReader($_.Exception.Response.GetResponseStream()); Write-Output $sr.ReadToEnd() }
}

$js = @'
const crypto = require('crypto');
const key = Buffer.from('A-16-Byte-keyVal','utf8');
const iv = Buffer.from('A-16-Byte-String','utf8');
function dec(b64){ const d=crypto.createDecipheriv('aes-128-cbc',key,iv); let o=d.update(b64,'base64','utf8'); o+=d.final('utf8'); return o; }
console.log('KNOWN DECRYPT (expect SIPPS@666):', dec('YNgpxUfKFMqdompB+t9SEA=='));
'@
$js | Out-File "$env:TEMP\dec.js" -Encoding utf8
node "$env:TEMP\dec.js"

$js = @'
const key = 'A-16-Byte-keyVal';
const iv = 'A-16-Byte-String';
console.log('KEY chars:', key.length, JSON.stringify(key.split('')));
console.log('IV chars:', iv.length);
const crypto=require('crypto');
const kb=Buffer.from(key,'utf8'), ib=Buffer.from(iv,'utf8');
console.log('KEY bytes',kb.length,'IV bytes',ib.length);
// try with key truncated to 16
function dec(b64,k){ const d=crypto.createDecipheriv('aes-128-cbc',k,ib); let o=d.update(b64,'base64','utf8'); o+=d.final('utf8'); return o; }
try { console.log('with full key:', dec('YNgpxUfKFMqdompB+t9SEA==', kb)); } catch(e){ console.log('full key fail:', e.code); }
try { console.log('with 16-byte key:', dec('YNgpxUfKFMqdompB+t9SEA==', kb.subarray(0,16))); } catch(e){ console.log('16 fail:', e.code); }
'@
$js | Out-File "$env:TEMP\dec2.js" -Encoding utf8
node "$env:TEMP\dec2.js"

$logs = @(
 "D:\repository\苏住房后端\logs\common-framework\debug.log",
