foreach ($pid_ in 29504,21768,14220,14836,23088) {
  $p = Get-CimInstance Win32_Process -Filter "ProcessId=$pid_" -ErrorAction SilentlyContinue
  if ($p) {
    $cl = $p.CommandLine
    # extract the jar path or main class
    Write-Output "PID $pid_ : $($p.Name)"
    if ($cl) { Write-Output ("   CMD: " + ($cl.Substring(0,[Math]::Min(400,$cl.Length)))) }
  }
}

# Check the packaged jar's internal bootstrap for the ACTUAL running config
$jars = @{
 "common-framework"="D:\repository\苏住房后端\common-framework\common-framework-server\target\common-framework-server.jar";
 "service-expand"="D:\repository\苏住房后端\service-expand\service-expand-server\target\service-expand-server.jar"
}
foreach ($k in $jars.Keys) {
  $jar=$jars[$k]
  $tmp="$env:TEMP\bs_$k.yml"
  # extract BOOT-INF/classes/bootstrap.yml using .NET ZipFile
  Add-Type -AssemblyName System.IO.Compression.FileSystem
  $zip=[System.IO.Compression.ZipFile]::OpenRead($jar)
  $entry=$zip.Entries | Where-Object { $_.FullName -eq "BOOT-INF/classes/bootstrap.yml" }
  if ($entry) {
    $sr=New-Object System.IO.StreamReader($entry.Open())
    $content=$sr.ReadToEnd(); $sr.Close()
    Write-Output "=== $k (in-jar bootstrap.yml) ==="
    ($content -split "`n" | Select-String "active|server-addr|namespace|port")
  } else { Write-Output "$k : no bootstrap.yml in jar" }
  $zip.Dispose()
}

# Can we reach nacos dev/test?
foreach ($h in "nacos.dev.zhi.com","nacos.test.zhi.com") {
  try { $r=Resolve-DnsName $h -ErrorAction Stop; Write-Output "$h => $($r.IPAddress -join ',')" } catch { Write-Output "$h => DNS FAIL: $($_.Exception.Message)" }
}
